package operationlog

const sqliteSchema = `PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS operation_log_owner_leases (lease_key TEXT PRIMARY KEY, owner_id TEXT NOT NULL, fence_token INTEGER NOT NULL, lease_until TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operation_logs (id TEXT PRIMARY KEY, trace_id TEXT, actor_system_account_id TEXT NOT NULL, actor_username TEXT, actor_display_name TEXT, actor_role TEXT NOT NULL, operation_scope_system_account_id TEXT, mode TEXT NOT NULL, module TEXT NOT NULL, action TEXT NOT NULL, operation_key TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, resource_name TEXT, summary TEXT NOT NULL, detail_level TEXT NOT NULL, visibility_scope TEXT NOT NULL, changes_json TEXT NOT NULL, metadata_json TEXT NOT NULL, method TEXT, path TEXT, status_code INTEGER, client_ip TEXT, user_agent TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operation_log_targets (id TEXT PRIMARY KEY, operation_log_id TEXT NOT NULL REFERENCES operation_logs(id) ON DELETE CASCADE, target_type TEXT NOT NULL, target_id TEXT, target_name TEXT, target_owner_system_account_id TEXT, relation TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operation_log_viewers (operation_log_id TEXT NOT NULL REFERENCES operation_logs(id) ON DELETE CASCADE, system_account_id TEXT NOT NULL, visibility_reason TEXT NOT NULL, detail_level TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(operation_log_id,system_account_id,visibility_reason,detail_level));
CREATE TABLE IF NOT EXISTS operation_log_summary_search_terms (operation_log_id TEXT NOT NULL REFERENCES operation_logs(id) ON DELETE CASCADE, term TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(term,operation_log_id));
CREATE INDEX IF NOT EXISTS idx_operation_logs_created ON operation_logs(created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_actor_created ON operation_logs(actor_system_account_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_scope_created ON operation_logs(operation_scope_system_account_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_module_action_created ON operation_logs(module,action,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_resource_created ON operation_logs(resource_type,resource_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_resource_id_created ON operation_logs(resource_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_visibility_created ON operation_logs(visibility_scope,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_trace_created ON operation_logs(trace_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_log_targets_log ON operation_log_targets(operation_log_id); CREATE INDEX IF NOT EXISTS idx_operation_log_targets_target ON operation_log_targets(target_type,target_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_log_viewers_account_created ON operation_log_viewers(system_account_id,created_at,operation_log_id); CREATE INDEX IF NOT EXISTS idx_operation_log_terms_log ON operation_log_summary_search_terms(operation_log_id); CREATE INDEX IF NOT EXISTS idx_operation_log_summary_search_terms_term_created ON operation_log_summary_search_terms(term,created_at,operation_log_id);`
const postgresSchema = `CREATE SCHEMA IF NOT EXISTS juhe_dataset; CREATE TABLE IF NOT EXISTS juhe_dataset.operation_log_owner_leases (lease_key text PRIMARY KEY, owner_id text NOT NULL, fence_token bigint NOT NULL, lease_until timestamptz NOT NULL, updated_at timestamptz NOT NULL); CREATE TABLE IF NOT EXISTS juhe_dataset.operation_logs (id text PRIMARY KEY, trace_id text, actor_system_account_id text NOT NULL, actor_username text, actor_display_name text, actor_role text NOT NULL, operation_scope_system_account_id text, mode text NOT NULL, module text NOT NULL, action text NOT NULL, operation_key text NOT NULL, resource_type text NOT NULL, resource_id text, resource_name text, summary text NOT NULL, detail_level text NOT NULL, visibility_scope text NOT NULL, changes_json jsonb NOT NULL, metadata_json jsonb NOT NULL, method text, path text, status_code integer, client_ip text, user_agent text, created_at timestamptz NOT NULL); CREATE TABLE IF NOT EXISTS juhe_dataset.operation_log_targets (id text PRIMARY KEY, operation_log_id text NOT NULL REFERENCES juhe_dataset.operation_logs(id) ON DELETE CASCADE, target_type text NOT NULL,target_id text,target_name text,target_owner_system_account_id text,relation text NOT NULL,created_at timestamptz NOT NULL); CREATE TABLE IF NOT EXISTS juhe_dataset.operation_log_viewers (operation_log_id text NOT NULL REFERENCES juhe_dataset.operation_logs(id) ON DELETE CASCADE,system_account_id text NOT NULL,visibility_reason text NOT NULL,detail_level text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(operation_log_id,system_account_id,visibility_reason,detail_level)); CREATE TABLE IF NOT EXISTS juhe_dataset.operation_log_summary_search_terms (operation_log_id text NOT NULL REFERENCES juhe_dataset.operation_logs(id) ON DELETE CASCADE,term text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(term,operation_log_id)); CREATE INDEX IF NOT EXISTS idx_operation_logs_created ON juhe_dataset.operation_logs(created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_actor_created ON juhe_dataset.operation_logs(actor_system_account_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_scope_created ON juhe_dataset.operation_logs(operation_scope_system_account_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_module_action_created ON juhe_dataset.operation_logs(module,action,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_resource_created ON juhe_dataset.operation_logs(resource_type,resource_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_resource_id_created ON juhe_dataset.operation_logs(resource_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_visibility_created ON juhe_dataset.operation_logs(visibility_scope,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_trace_created ON juhe_dataset.operation_logs(trace_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_logs_trace_c_created ON juhe_dataset.operation_logs((trace_id COLLATE "C"),created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_log_targets_log ON juhe_dataset.operation_log_targets(operation_log_id); CREATE INDEX IF NOT EXISTS idx_operation_log_targets_target ON juhe_dataset.operation_log_targets(target_type,target_id,created_at,id); CREATE INDEX IF NOT EXISTS idx_operation_log_viewers_account_created ON juhe_dataset.operation_log_viewers(system_account_id,created_at,operation_log_id); CREATE INDEX IF NOT EXISTS idx_operation_log_terms_log ON juhe_dataset.operation_log_summary_search_terms(operation_log_id); CREATE INDEX IF NOT EXISTS idx_operation_log_summary_search_terms_term_created ON juhe_dataset.operation_log_summary_search_terms(term,created_at,operation_log_id);`
